def transform(grid):
    h, w = len(grid), len(grid[0])
    def lattice(n):
        start = next((i for i in range(n) if any(grid[i][j] != 0 for j in range(w))) if n == h else (next((j for j in range(w) if any(grid[i][j] != 0 for i in range(h))), None)), None)
        if start is None:
            return []
        # The first colored tile is a solid run; two blank rows/columns separate tiles.
        if n == h:
            length = 0
            while start + length < h and any(grid[start + length][j] != 0 for j in range(w)):
                length += 1
        else:
            length = 0
            while start + length < w and any(grid[i][start + length] != 0 for i in range(h)):
                length += 1
        pitch = length + 2
        center = start + length // 2
        return list(range(center, n, pitch))
    rows, cols = lattice(h), lattice(w)
    out = [row[:] for row in grid]
    centers = {(r, c): grid[r][c] for r in rows for c in cols}
    from collections import Counter
    base = Counter(centers.values()).most_common(1)[0][0]
    colors = set(centers.values()) - {base}
    for color in colors:
        for r in rows:
            cs = [c for c in cols if centers[(r,c)] == color]
            if len(cs) >= 2:
                for c in range(min(cs), max(cs)+1): out[r][c] = color
        for c in cols:
            rs = [r for r in rows if centers[(r,c)] == color]
            if len(rs) >= 2:
                for r in range(min(rs), max(rs)+1): out[r][c] = color
    return out

